public class DfsDemo {

    private static final Logger log = Logger.getLogger(DfsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Map<String, List<String>> graph = new java.util.HashMap<>();
        graph.put("SAV2001", List.of("CUR3001"));          // Rajesh → Priya
        graph.put("CUR3001", List.of("SAV4002"));          // Priya → Amit
