class MoneyTrailDFS {

    private static final Logger log = Logger.getLogger(MoneyTrailDFS.class.getName());

    private final Map<String, List<String>> graph;

    MoneyTrailDFS(Map<String, List<String>> graph) {
        this.graph = graph;
    }

    // Public entry: trace the trail depth-first from the start.
    void trace(String start) {
        java.util.Set<String> visited = new java.util.HashSet<>();
        dive(start, visited);
        log.info(() -> "DFS trace complete. Visited " + visited.size() + " accounts.");
    }

    // Recursive dive: go deep, then backtrack.
    private void dive(String account, java.util.Set<String> visited) {
        if (!visited.add(account)) return;   // already visited → backtrack
        log.info(() -> "Dive into " + account);
        for (String next : graph.getOrDefault(account, List.of())) {
            dive(next, visited);              // go deeper first
        }
        log.fine(() -> "Backtrack from " + account);
    }

    // Cycle detection: a back edge to a node on the current recursion path.
    boolean hasCycle(String start) {
        return detect(start, new java.util.HashSet<>(), new java.util.HashSet<>());
    }

    private boolean detect(String node, java.util.Set<String> onPath, java.util.Set<String> done) {
        if (onPath.contains(node)) return true;   // back edge → cycle
        if (done.contains(node)) return false;    // fully explored, no cycle here
        onPath.add(node);
        for (String next : graph.getOrDefault(node, List.of())) {
            if (detect(next, onPath, done)) return true;
        }
        onPath.remove(node);                        // leaving the active path
        done.add(node);
        return false;
    }
}

